public class Solution {
    public int removeDuplicates(int[] nums) {
        java.util.List<Integer> r = new java.util.ArrayList<>();
        for (int x : nums) if (!r.contains(x)) r.add(x);  // O(n^2)
        for (int i = 0; i < r.size(); i++) nums[i] = r.get(i);
        return r.size();
    }
}
